// Letter texts and template placeholders - port of pipeline/letter.py (letter_values, PLACEHOLDERS, penalty rows).
// Parity with Python is checked by shared/letter.test.ts on data generated by scripts/export_schemas.py.
import { EVENT_LABELS, type PenaltyResult, fmtDate, formatPln, isoOf, dayNum } from "./calculator";
import { demanded } from "./adapter";

export const DRAFT_BANNER = "PROJEKT — do weryfikacji i podpisu przez pełnomocnika";
const missing = (label: string) => `[UZUPEŁNIJ: ${label}]`;
const orMissing = (value: string | undefined, label: string) => (value ?? "").trim() || missing(label);

export const PLACEHOLDERS: Record<string, string> = {
  draft_banner: "Nagłówek projektu",
  case_number: "Sygnatura sprawy",
  firm_name: "Kancelaria",
  firm_address: "Adres kancelarii",
  place_and_date: "Miejscowość i data",
  letter_date: "Data pisma",
  developer_name: "Deweloper",
  developer_address: "Adres dewelopera",
  client_names: "Mocodawcy (imiona i nazwiska)",
  clients: "Mocodawcy z adresami",
  agreement: "Umowa (opis do zdania)",
  agreement_date: "Data umowy",
  agreement_deed: "Numer aktu notarialnego umowy",
  total_amount: "Kwota żądania",
  payment_deadline_days: "Termin zapłaty (dni)",
  bank_account: "Rachunek do zapłaty",
  intro: "Wstęp (mocodawca, pełnomocnictwo, umowa)",
  demand: "Żądanie zapłaty",
  justification: "Uzasadnienie (projekt przygotowany przez model)",
  legal_basis: "Podstawa prawna",
  closing: "Zakończenie",
  lawyer: "Podpis (prawnik, tytuł)",
  lawyer_name: "Prawnik — imię i nazwisko",
  lawyer_title: "Prawnik — tytuł zawodowy",
  lawyer_registry: "Prawnik — numer wpisu",
};
export const TABLE_PLACEHOLDER = "penalty_rows";
export const MISSING_RE = /\[UZUPEŁNIJ: [^\]]+\]/g;

export interface LetterParties {
  clientName?: string;
  clientAddress?: string;
  clients?: [string, string][]; // (name, address) per client
  developerName?: string;
  developerAddress?: string;
  agreementReference?: string;
  agreementDate?: string; // DD.MM.RRRR
  agreementDeed?: string;
  bankAccount?: string;
  caseNumber?: string;
  lawyerName?: string;
  lawyerTitle?: string;
  lawyerRegistry?: string;
  firmName?: string;
  firmAddress?: string;
  city?: string;
  paymentDeadlineDays?: number;
  legalBasis?: string;
}

function clientsPhrase(p: LetterParties): string {
  const people = (p.clients ?? []).filter(([name]) => name).map(([name, address]) => `${name} (${orMissing(address, "adres mocodawcy")})`);
  if (people.length) return people.length === 1 ? people[0] : `${people.slice(0, -1).join(", ")} oraz ${people[people.length - 1]}`;
  return `${orMissing(p.clientName, "mocodawca")} (${orMissing(p.clientAddress, "adres mocodawcy")})`;
}

function agreementPhrase(p: LetterParties): string {
  if ((p.agreementReference ?? "").trim()) return p.agreementReference!.trim();
  if (p.agreementDate || p.agreementDeed) {
    const deed = p.agreementDeed ? ` zawartą w formie aktu notarialnego ${p.agreementDeed}` : "";
    return `umową deweloperską z dnia ${orMissing(p.agreementDate, "data umowy")}${deed}`;
  }
  return missing("data i numer umowy deweloperskiej");
}

/** Values for every placeholder, exactly as pipeline/letter.py letter_values (letterDate as ISO). */
export function letterValues(p: LetterParties, totalGrosze: bigint, justification: string, letterDate: string): Record<string, string> {
  const days = p.paymentDeadlineDays || 14;
  const lawyer = p.lawyerName ?? "";
  const signature = [lawyer, p.lawyerTitle ?? ""].filter(Boolean).join(", ");
  const clients = clientsPhrase(p);
  return {
    draft_banner: DRAFT_BANNER,
    firm_name: p.firmName ?? "",
    firm_address: p.firmAddress ?? "",
    place_and_date: `${p.city ?? ""}, dnia ${fmtDate(letterDate)}`,
    letter_date: fmtDate(letterDate),
    case_number: orMissing(p.caseNumber, "sygnatura sprawy"),
    developer_name: orMissing(p.developerName, "nazwa dewelopera"),
    developer_address: orMissing(p.developerAddress, "adres dewelopera"),
    client_names: orMissing(p.clientName, "mocodawca"),
    clients,
    agreement: agreementPhrase(p),
    agreement_date: orMissing(p.agreementDate, "data umowy"),
    agreement_deed: orMissing(p.agreementDeed, "numer aktu notarialnego umowy"),
    total_amount: formatPln(totalGrosze),
    payment_deadline_days: String(days),
    bank_account: orMissing(p.bankAccount, "numer rachunku"),
    intro: `Działając w imieniu i na rzecz ${clients}, na podstawie udzielonego pełnomocnictwa, w związku z ${agreementPhrase(p)}, niniejszym:`,
    demand: `wzywam do zapłaty kwoty ${formatPln(totalGrosze)} tytułem kar umownych za opóźnienie, w terminie ${days} dni od dnia doręczenia niniejszego wezwania, na rachunek bankowy nr ${orMissing(p.bankAccount, "numer rachunku")}.`,
    justification,
    legal_basis: p.legalBasis || missing("podstawa prawna roszczenia"),
    closing: "Brak zapłaty we wskazanym terminie spowoduje skierowanie sprawy na drogę postępowania sądowego bez dalszego wezwania.",
    lawyer: signature,
    lawyer_name: orMissing(lawyer, "imię i nazwisko pełnomocnika"),
    lawyer_title: p.lawyerTitle ?? "",
    lawyer_registry: p.lawyerRegistry ?? "",
  };
}

export type Row = [string, string, string, string];

/** Calculation table rows, as pipeline/letter.py penalty_rows. */
export function penaltyRows(penalties: PenaltyResult[], capped: boolean): Row[] {
  return penalties.filter((p) => p.uncappedGrosze !== null).map((p) => {
    const start = fmtDate(isoOf(dayNum(p.effectiveDeadline.deadline) + 1));
    const end = fmtDate(p.endDate) + (p.ongoing ? " (trwa)" : "");
    const label = EVENT_LABELS[p.event];
    return [label.charAt(0).toUpperCase() + label.slice(1), `${start} – ${end}`, String(p.days), formatPln(demanded(p, capped))];
  });
}

export function missingFields(values: Record<string, string>): string[] {
  return [...new Set(Object.values(values).flatMap((v) => v.match(MISSING_RE) ?? []))].sort();
}
